async function run() {
  const ws = figma.root.children.find(p => p.name === '03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  console.log('current page: ' + figma.currentPage.name);

  // Inspect Button component
  function findComp(name){
    for (const page of figma.root.children){
      const c = page.findOne(n => n.type === 'COMPONENT' && n.name === name);
      if (c) return c;
    }
    return null;
  }
  const btn = findComp('Button');
  const info = [];
  if (btn) {
    function walk(n, depth){
      const r = {name:n.name, type:n.type};
      if (n.type==='TEXT') r.chars = n.characters, r.style = {ff:n.fontName?.family||'', st:n.fontName?.style||'', size:n.fontSize};
      r.children = (n.children||[]).map(c=>walk(c,depth+1));
      return r;
    }
    info.push({nodeName:btn.name, id:btn.id, key:btn.key, children: btn.children.map(c=>walk(c,1))});
  }
  // media components names
  const mediaNames = [];
  const mediaPage = figma.root.children.find(p => p.name === '04 · Media');
  if (mediaPage){
    mediaPage.findAll(n => n.type==='COMPONENT').forEach(c=>mediaNames.push({name:c.name, id:c.id}));
  }
  console.log(JSON.stringify({button:info, mediaComponents: mediaNames}, null, 2));
}
