async function run() {
  const ws = figma.root.children.find(p => p.name === '03 · Workspace');
  await figma.setCurrentPageAsync(ws);

  // Load fonts
  const families = { 'Plus Jakarta Sans': ['Regular','Medium','SemiBold','Bold','ExtraBold'] };
  for (const [fam, styles] of Object.entries(families)){
    for (const st of styles){
      try { await figma.loadFontAsync({family: fam, style: st}); } catch(e){ console.log('font fail '+fam+' '+st); }
    }
  }

  function findMain(name, pageContext){
    const pool = figma.root.children.slice();
    let comp=null;
    for (const p of pool){
      comp = p.findOne(n => n.type==='COMPONENT' && n.name===name);
      if (comp) break;
    }
    return comp;
  }

  const names = ['Button','Logo_MAC','Logo_Facebook','Logo_Twitter','Logo_LinkedIn','Logo_Instagram',
    'Icon_Arrow_Left','Icon_Arrow_Right','Icon_Bell','Icon_Chevron_Down','Icon_Mail','Icon_Map_Pin',
    'Icon_Minus','Icon_Phone','Icon_Play','Icon_Plus','Icon_Trending_Up'];

  const hosts = {};
  const report = [];
  for (const nm of names){
    const comp = findMain(nm);
    if (!comp){ console.log('MISSING '+nm); continue; }
    let host = hosts[nm.replace(/[/.]/g,'_')];
    const inst = figma.createInstanceFromComponent(comp);
    inst.name = nm+'_inst';
    report.push({name:nm, instId:inst.id, children: inst.children.map(c=>({name:c.name,type:c.type, id:c.id}))});
    inst.x = 50; inst.y = 50;
    inst.remove();
  }
  // Re-create a staging frame with instances we need access to (button structure)
  const btnComp = findMain('Button');
  const btnInst = figma.createInstanceFromComponent(btnComp);
  btnInst.name = 'staging_btn';
  const btnInfo = btnInst.children.map(c=>({name:c.name, type:c.type}));
  figma.root.children.find(p=>p.name==='03 · Workspace').appendChild(btnInst);
  btnInst.x = 50; btnInst.y = 50;
  console.log(JSON.stringify(report));
  console.log('BTN '+JSON.stringify(btnInfo));
}
