async function run(){
  function info(n){
    if(n.type==='TEXT'){ return {name:n.name, chars:n.characters, font:JSON.stringify(n.fontName), size:n.fontSize, fills:JSON.stringify(n.fills)}; }
    if(n.children){ return n.children.map(info).filter(Boolean); }
  }
  let btn=null, logo=null, icon=null;
  for(const p of figma.root.children){
    if(!btn) btn=p.findOne(n=>n.name==='Button'&&n.type==='COMPONENT'||n.name==='Button'&&n.type==='INSTANCE'||n.name==='Button') ;
    if(!logo) logo=p.findOne(n=>n.name==='Logo_MAC');
    if(!icon) icon=p.findOne(n=>n.name==='Icon_Arrow_Right');
  }
  const out={};
  if(btn) out.btn=info(btn);
  if(logo) out.logo=info(logo);
  if(icon) out.iconArrow=info(icon);
  const globals=(typeof XMLHttpRequest!=='undefined');
  console.log(JSON.stringify({btnId:btn&&btn.id, logoId:logo&&logo.id, iconId:icon&&icon.id, out}));
}
