    if(n.type==='TEXT'){
      if(n.fontName){ results.push(n.name+' :: '+n.fontName.family+' / '+n.fontName.style); }
    }
    if(n.children){ n.children.forEach(scan); }
  }
  const media = figma.root.children.find(p=>p.name==='04 · Media');
  if(media) media.findAll(n=>n.type==='TEXT').forEach(n=>results.push('MED:'+n.name+' :: '+n.fontName.family+' / '+n.fontName.style));
  // encode into rectangles on workspace
  const ws = figma.root.children.find(p=>p.name==='03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  const uniq = [...new Set(results)];
  for(let i=0;i<uniq.length;i++){
    const r=figma.createRectangle();
    r.resizeWithoutConstraints(20,10);
    r.fills=[{type:'SOLID',color:{r:0.9,g:0.9,b:0.9}}];
    r.name='F#'+(i+1)+':'+uniq[i].slice(0,60);
    ws.appendChild(r);
  }
}
