async function run(){
  const PJS='Plus Jakarta Sans';
  const ws = figma.root.children.find(p=>p.name==='03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  const page = ws.children.find(c=>c.name==='01_Home');
  await figma.loadFontAsync({family:PJS, style:'SemiBold'});
  const ink={r:0.004,g:0.008,b:0.02};
  const lime={r:0.6,g:0.917,b:0.28};

  function pill(name,label,lx,y,w,h){
    const r=figma.createRectangle();
    r.name=name+'_bg'; r.resizeWithoutConstraints(w,h);
    r.fills=[{type:'SOLID',color:lime}]; r.cornerRadius=28;
    r.x=lx; r.y=y; page.appendChild(r);
    const t=figma.createText();
    t.name=name+'_label'; t.characters=label;
    t.fontName={family:PJS, style:'SemiBold'}; t.fontSize=16;
    t.fills=[{type:'SOLID',color:ink}];
    t.x=lx+ (label.length>14?20:24); t.y=y+18; page.appendChild(t);
  }
  pill('CTA_ScheduleCall','Schedule Call',72,440,190,56);
  pill('CTA_ViewCaseStudy','View Case Study',282,440,190,56);
}
run();
